<div id="modal-editar-jornada-config" class="fixed inset-0 z-[70] hidden overflow-y-auto bg-slate-900/45 p-4"><div class="mx-auto mt-10 max-w-xl rounded-2xl bg-white p-6 shadow-2xl"><h2 class="text-lg font-bold">Editar jornada</h2><p class="mt-1 text-sm text-slate-500">El cambio se aplicará a marcaciones y cálculos abiertos posteriores.</p><form method="post" action="index.php?url=asistencia_configurar" data-confirmar-accion="config-jornada-editar" class="mt-5 grid gap-3 sm:grid-cols-2"><?= campoCsrf() ?><input type="hidden" name="entidad" value="jornada_actualizar"><input id="ecj-id" type="hidden" name="id_jornada"><label class="form-label sm:col-span-2">Nombre<input id="ecj-nombre" required maxlength="100" name="nombre" class="form-input"></label><label class="form-label">Aplica a<select id="ecj-aplica" name="aplica_a" class="form-input" data-aplica-jornada><option>ALUMNO</option><option>DOCENTE</option><option>ADMINISTRATIVO</option></select></label><label class="form-label">Tolerancia<input id="ecj-tolerancia" required min="0" max="180" type="number" name="tolerancia_minutos" class="form-input"></label><label class="form-label">Entrada<input id="ecj-entrada" required type="time" name="hora_entrada" class="form-input"></label><label class="form-label">Salida<input id="ecj-salida" required type="time" name="hora_salida" class="form-input"></label><label class="flex items-center gap-2 text-sm"><input id="ecj-requiere" type="checkbox" name="requiere_salida" data-requiere-salida> Requiere salida</label><label class="flex items-center gap-2 text-sm"><input id="ecj-predeterminada" type="checkbox" name="es_predeterminada" data-jornada-predeterminada> Predeterminada</label><button class="rounded-xl bg-amber-400 px-4 py-2.5 font-semibold text-amber-950 sm:col-span-2">Guardar cambios</button></form></div></div>

<div id="modal-editar-dispositivo-config" class="fixed inset-0 z-[70] hidden overflow-y-auto bg-slate-900/45 p-4"><div class="mx-auto mt-10 max-w-lg rounded-2xl bg-white p-6 shadow-2xl"><h2 class="text-lg font-bold">Editar dispositivo</h2><form method="post" action="index.php?url=asistencia_configurar" data-confirmar-accion="config-dispositivo-editar" class="mt-5 grid gap-3"><?= campoCsrf() ?><input type="hidden" name="entidad" value="dispositivo_actualizar"><input id="ecd-id" type="hidden" name="id_dispositivo"><label class="form-label">Nombre<input id="ecd-nombre" required maxlength="100" name="nombre" class="form-input"></label><label class="form-label">Código único<input id="ecd-codigo" required maxlength="50" pattern="[A-Za-z0-9-]+" name="codigo" class="form-input"><small id="ecd-codigo-ayuda" class="mt-1 block font-normal text-slate-500"></small></label><label class="form-label">Punto de control<input id="ecd-punto" required maxlength="120" name="punto_control" class="form-input"></label><button class="rounded-xl bg-amber-400 px-4 py-2.5 font-semibold text-amber-950">Guardar cambios</button></form></div></div>

<script>
document.addEventListener('DOMContentLoaded',()=>{
    const ajustarJornada=(contenedor)=>{const aplica=contenedor.querySelector('[data-aplica-jornada]');const salida=contenedor.querySelector('[data-requiere-salida]');const pred=contenedor.querySelector('[data-jornada-predeterminada]');if(!aplica)return;const actualizar=()=>{const alumno=aplica.value==='ALUMNO';salida.disabled=alumno;if(alumno)salida.checked=false;pred.disabled=!alumno;if(!alumno)pred.checked=false;};aplica.addEventListener('change',actualizar);actualizar();};
    document.querySelectorAll('form').forEach(ajustarJornada);
    document.querySelectorAll('.btn-editar-jornada-config').forEach(b=>b.addEventListener('click',()=>{const m=document.getElementById('modal-editar-jornada-config');document.getElementById('ecj-id').value=b.dataset.id;document.getElementById('ecj-nombre').value=b.dataset.nombre;document.getElementById('ecj-aplica').value=b.dataset.aplica;document.getElementById('ecj-entrada').value=b.dataset.entrada;document.getElementById('ecj-salida').value=b.dataset.salida;document.getElementById('ecj-tolerancia').value=b.dataset.tolerancia;document.getElementById('ecj-requiere').checked=b.dataset.requiere==='1';document.getElementById('ecj-predeterminada').checked=b.dataset.predeterminada==='1';ajustarJornada(m);m.classList.remove('hidden');}));
    document.querySelectorAll('.btn-editar-dispositivo-config').forEach(b=>b.addEventListener('click',()=>{const m=document.getElementById('modal-editar-dispositivo-config');const usado=Number(b.dataset.marcaciones)>0;document.getElementById('ecd-id').value=b.dataset.id;document.getElementById('ecd-nombre').value=b.dataset.nombre;document.getElementById('ecd-codigo').value=b.dataset.codigo;document.getElementById('ecd-codigo').readOnly=usado;document.getElementById('ecd-codigo-ayuda').textContent=usado?'El código está protegido porque el dispositivo ya tiene marcaciones.':'Puede corregir el código mientras no tenga marcaciones.';document.getElementById('ecd-punto').value=b.dataset.punto;m.classList.remove('hidden');}));
});
</script>
